   "html": "<div class=\"manual-table\"><table><thead><tr><th>REF DES<\/th><th>DESCRIPTION<\/th><th>FLUKE STOCK NO.<\/th><th>MFG SPLY CODE<\/th><th>MFG PART NO.<\/th><th>TOT QTY<\/th><th>REC QTY<\/th><th>NOTE<\/th><\/tr><\/thead><tbody><tr><td>A7<\/td><td>CALIBRATION PCB ASSEMBLY<br>FIGURE 5-8 (732A-4007)<br>includes cable<\/td><td>645028<\/td><td>89536<\/td><td>645028<\/td><td>REF<\/td><td><\/td><td><\/td><\/tr><\/tbody><\/table><\/div>\n<p>Page footer: \"5-24\"<\/p>",
